use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    /// Drop every item whose id is already recorded in the `seen` store.
    /// Items are keyed by their parser-computed id. Order is preserved.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        let mut kept = Vec::with_capacity(items.len());
        for item in items {
            if state_read::get(&item.id).is_none() {
                kept.push(item);
            }
        }
        kept
    }
}

export!(Node);
